#!/usr/bin/env python3
"""Спрайты уровней (DarkestHour): люк с лестницей вниз, лестница наверх, пульт и платформа грузового лифта.

Запуск из корня репозитория:  python3 Tools/_DarkestHour/bunker/build.py
"""
import json
import os

from PIL import Image, ImageDraw

ROOT = 'Resources/Textures/_DarkestHour/Structures/Levels'
META = {'version': 1, 'license': 'CC-BY-SA-3.0',
        'copyright': 'DarkestHour, generated by Tools/_DarkestHour/bunker/build.py'}

STEEL = (92, 98, 104, 255)
STEEL_D = (58, 62, 67, 255)
STEEL_L = (138, 146, 152, 255)
RUST = (120, 84, 52, 255)
YELLOW = (214, 170, 46, 255)
BLACK = (14, 14, 16, 255)


def save_rsi(name, size, states):
    path = os.path.join(ROOT, name + '.rsi')
    os.makedirs(path, exist_ok=True)
    meta = dict(META, size={'x': size, 'y': size}, states=[])
    for state, img in states:
        img.save(os.path.join(path, state + '.png'))
        meta['states'].append({'name': state})
    with open(os.path.join(path, 'meta.json'), 'w') as f:
        json.dump(meta, f)
        f.write('\n')
    print(path)


def hatch():
    """Открытый люк в полу: рама, откинутая крышка, тёмный колодец с перекладинами."""
    im = Image.new('RGBA', (32, 32), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    d.rectangle([4, 6, 27, 29], fill=STEEL_D)
    d.rectangle([6, 8, 25, 27], fill=BLACK)
    for y in range(10, 27, 4):  # перекладины, уходящие в темноту
        shade = max(30, 120 - (y - 10) * 6)
        d.line([10, y, 21, y], fill=(shade, shade, shade + 6, 255))
    d.line([10, 9, 10, 27], fill=(70, 72, 76, 255))
    d.line([21, 9, 21, 27], fill=(70, 72, 76, 255))
    d.rectangle([4, 1, 27, 6], fill=STEEL)  # откинутая крышка
    d.line([4, 1, 27, 1], fill=STEEL_L)
    d.line([8, 3, 23, 3], fill=STEEL_D)
    for x in range(4, 28, 4):  # жёлто-чёрная окантовка
        d.rectangle([x, 28, x + 1, 29], fill=YELLOW)
    return im


def ladder():
    """Лестница наверх у стены: стальные стойки, перекладины, свет сверху."""
    im = Image.new('RGBA', (32, 32), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    d.rectangle([8, 0, 23, 6], fill=(170, 160, 120, 120))  # свет из люка
    d.rectangle([9, 0, 11, 31], fill=STEEL)
    d.rectangle([20, 0, 22, 31], fill=STEEL)
    d.line([9, 0, 9, 31], fill=STEEL_L)
    d.line([20, 0, 20, 31], fill=STEEL_L)
    for y in range(3, 31, 5):
        d.rectangle([12, y, 19, y + 1], fill=STEEL_L)
        d.line([12, y + 2, 19, y + 2], fill=STEEL_D)
    return im


def panel():
    """Пульт лифта на стойке: две кнопки и лампа."""
    im = Image.new('RGBA', (32, 32), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    d.rectangle([13, 18, 18, 30], fill=STEEL_D)
    d.rectangle([8, 6, 23, 19], fill=STEEL)
    d.rectangle([9, 7, 22, 18], outline=STEEL_D)
    d.ellipse([11, 9, 15, 13], fill=(60, 170, 70, 255))
    d.ellipse([16, 9, 20, 13], fill=(190, 60, 50, 255))
    d.rectangle([12, 15, 19, 16], fill=YELLOW)
    return im


def platform():
    """Платформа грузового лифта 3x3: рифлёная сталь, жёлто-чёрная кайма по краю."""
    s = 96
    im = Image.new('RGBA', (s, s), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    d.rectangle([0, 0, s - 1, s - 1], fill=STEEL_D)
    for y in range(8, s - 8, 6):
        for x in range(8 + (y // 6) % 2 * 3, s - 8, 6):
            d.line([x, y, x + 2, y + 2], fill=STEEL_L)
    for i in range(0, s, 8):
        for (x0, y0, x1, y1) in ((i, 0, i + 3, 5), (i, s - 6, i + 3, s - 1), (0, i, 5, i + 3), (s - 6, i, s - 1, i + 3)):
            d.rectangle([x0, y0, x1, y1], fill=YELLOW)
    d.rectangle([0, 0, s - 1, s - 1], outline=BLACK)
    for cx, cy in ((10, 10), (s - 11, 10), (10, s - 11), (s - 11, s - 11)):
        d.ellipse([cx - 2, cy - 2, cx + 2, cy + 2], fill=RUST)
    return im


if __name__ == '__main__':
    save_rsi('levels', 32, [('hatch', hatch()), ('ladder', ladder()), ('lift_panel', panel())])
    save_rsi('lift', 96, [('platform', platform())])
